```ts
// audioClipSourceEndBeat.ts
import { captureAudioSourceState, getAudioTimelineElapsedSeconds } from '#/utils/audioSourceTime';
import { hasExactAudioSourceFields } from '#/utils/hasExactAudioSourceFields';

import { type TempoTimeline } from '../../models/TempoTimeline';
import { type Clip } from '../../models/Track';

import { consumedStretchFactor } from './consumedStretchFactor';

/**
 * The beat at which a non-looping audio clip's source runs out. Playback reads
 * source second `E + r * (song seconds since the clip start)`, so a source of
 * `D` seconds is used up `(D - E) / r` song seconds after the clip start, read
 * back as a beat through the tempo map's own inverse. A negative entry (the
 * clip opening in silence before its media) lengthens that span by the
 * pre-roll it plays first.
 *
 * `null` when the clip has no such end (a MIDI or looping clip) or its source
 * position cannot be read.
 */
export function audioClipSourceEndBeat(
    clip: Clip,
    sourceDurationSeconds: number,
    timeline: TempoTimeline
): number | null {
    if (clip.type !== 'audio' || clip.loopEnabled || !hasExactAudioSourceFields(clip)) {
        return null;
    }
    if (!Number.isFinite(sourceDurationSeconds) || sourceDurationSeconds <= 0) {
        return null;
    }
    const source = captureAudioSourceState(clip, clip.endBeat - clip.startBeat, timeline.tempoAtBeat(clip.startBeat));
    if (!source) {
        return null;
    }
    const remainingSongSeconds = getAudioTimelineElapsedSeconds(
        source.audioOffsetSeconds,
        sourceDurationSeconds,
        consumedStretchFactor(clip)
    );
    const endBeat = timeline.beatAtSeconds(timeline.secondsAtBeat(clip.startBeat) + remainingSongSeconds);
    return Number.isFinite(endBeat) ? endBeat : null;
}

// limitClipEndToSource.ts
import { getCachedAudioBuffer } from '#/modules/AudioEngine/useCases';
import { CLIP_LOOP_WINDOW_BEAT_TOLERANCE } from '#/utils/clipLoopOrigin';

import { type TempoTimeline } from '../../models/TempoTimeline';
import { type Clip } from '../../models/Track';
import { liveTempoTimeline } from '../liveTempoTimeline';

import { audioClipSourceEndBeat } from './audioClipSourceEndBeat';

/**
 * The end a user's request to move a clip's end to `requestedEndBeat` may
 * reach. A non-looping audio clip grows at most to the beat its source runs out
 * on, as an unlooped region does in Logic, Pro Tools and Ableton; a clip
 * already past that beat does not grow. Shortening, looping and MIDI clips, and
 * a clip whose decoded source is not cached, keep the requested end.
 *
 * The bound belongs where a request is formed, never in `trimClipEnd`: undo,
 * redo and replay write the recorded end exactly, whatever the source and the
 * buffer cache say at that moment.
 */
export function limitClipEndToSource(
    clip: Clip,
    requestedEndBeat: number,
    timeline: TempoTimeline = liveTempoTimeline
): number {
    if (requestedEndBeat <= clip.endBeat || clip.audioBufferId === undefined) {
        return requestedEndBeat;
    }
    const buffer = getCachedAudioBuffer({ bufferId: clip.audioBufferId });
    if (!buffer) {
        return requestedEndBeat;
    }
    const sourceEndBeat = audioClipSourceEndBeat(clip, buffer.length / buffer.sampleRate, timeline);
    if (sourceEndBeat === null || requestedEndBeat - sourceEndBeat <= CLIP_LOOP_WINDOW_BEAT_TOLERANCE) {
        return requestedEndBeat;
    }
    return Math.max(clip.endBeat, sourceEndBeat);
}

// getClipEndLimit.ts
import { getTrackState } from '../../repositories/track/getTrackState';
import { findClipById } from '../../services/findClipById';

import { limitClipEndToSource } from './limitClipEndToSource';

/**
 * The farthest end a user may give the clip `clipId` by moving its end, or
 * `null` when nothing but the editor's own range limits it: the clip is gone,
 * loops, is MIDI, or its decoded source is not cached. Controls that set an end
 * directly take their maximum from here, so they stop where the timeline edge
 * stops.
 */
export function getClipEndLimit(clipId: string): number | null {
    const found = findClipById({ clipId, tracks: getTrackState()?.tracks ?? [] });
    if (!found) {
        return null;
    }
    const limit = limitClipEndToSource(found.clip, Number.POSITIVE_INFINITY);
    return Number.isFinite(limit) ? limit : null;
}
```

